	/**
	 * Default Constructor
	 */
    public EquityGrantService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new EquityGrantEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(EquityGrantRepository.class) );
		this.validator		= applicationContext.getBean(EquityGrantValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		EquityGrant
	 */
		public EquityGrant createEquityGrant( CreateEquityGrantCommand command ) {

		EquityGrant entity = new EquityGrant();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setEquityGrantId( command.getEquityGrantId() );
            entity.setGrantId( command.getGrantId() );
            entity.setGrantedUnits( command.getGrantedUnits() );
            entity.setVestingStart( command.getVestingStart() );
            entity.setGrantType( command.getGrantType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of EquityGrant {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateEquityGrantCommand
	 * @return		EquityGrant
	 */
	public EquityGrant updateEquityGrant( UpdateEquityGrantCommand command ) {

		EquityGrant entity = new EquityGrant();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setEquityGrantId( command.getEquityGrantId() );
            entity.setGrantId( command.getGrantId() );
            entity.setGrantedUnits( command.getGrantedUnits() );
            entity.setVestingStart( command.getVestingStart() );
            entity.setCompensationPackage( command.getCompensationPackage() );
            entity.setGrantType( command.getGrantType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of EquityGrant {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteEquityGrantCommand
	 */
	public void delete( DeleteEquityGrantCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getEquityGrantId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of EquityGrant {0} ", id );

	}

	/**
	 * Method to retrieve the EquityGrant via EquityGrantFetchOneSummary
	 * @param 	summary EquityGrantFetchOneSummary
	 * @return 	EquityGrantFetchOneResponse
	 */
	public EquityGrant getEquityGrant( EquityGrantFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "EquityGrantFetchOneSummary arg cannot be null" );

		EquityGrant entity = null;
		UUID id = summary.getEquityGrantId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a EquityGrant using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all EquityGrants
	 *
	 * @return 	List<EquityGrant>
	 */
    public List<EquityGrant> getAllEquityGrant() {
		List<EquityGrant> list = projector.findAll( new FindAllEquityGrantQuery() );
		return list;
	}

	/**
	 * assign CompensationPackage on EquityGrant
	 * @param		command AssignCompensationPackageToEquityGrantCommand
	 */
	public void assignCompensationPackage( AssignCompensationPackageToEquityGrantCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCompensationPackage(command.getEquityGrantId(), command.getAssignment());

	}

	/**
	 * unAssign CompensationPackage on EquityGrant
	 * @param		command UnAssignCompensationPackageFromEquityGrantCommand
	 */
	public void unAssignCompensationPackage( UnAssignCompensationPackageFromEquityGrantCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignCompensationPackage(command.getEquityGrantId());
	}
	




